import { Block, Screen, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { MatrixService } from "modules/matrix-client/services";
import { addDateDividers, getEventId } from "modules/matrix-client/utils";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  ActivityIndicator,
  FlatList,
  Image,
  KeyboardAvoidingView,
  type NativeScrollEvent,
  type NativeSyntheticEvent,
  StyleSheet,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { Button, Loading } from "shared/components";
import { Colors } from "shared/styles";
import {
  DateDivider,
  RoomHeader,
  RoomInput,
  SingleMessageType,
} from "./fragments";
import { useRoomInitialization, useRoomTimeline } from "./hooks";
import { filterSameStateKey, handleIsPreviousSameSender } from "./utils";

export const Room: React.FC<NativeStackScreenProps<Routes, "room">> = ({
  route,
  navigation,
}) => {
  const { roomId } = route.params;
  const client = MatrixService.instance;
  const room = client?.getRoom(roomId);
  const insets = useSafeAreaInsets();
  const flatListRef = useRef<FlatList>(null);
  /* Track whether list is scrolled to bottom */
  const isAtBottomRef = useRef(true);
  const [showScrollDown, setShowScrollDown] = useState(false);
  const hasActiveCall = room?.hasActiveRoomCall();

  const {
    events,
    loadingMessage,
    refreshing,
    updateTrigger,
    loadMoreMessages,
    markAsRead,
  } = useRoomTimeline({ room, roomId });

  const { roomMembers, hasNoCallOption } = useRoomInitialization({ room });

  const sortedEvents = useMemo(() => {
    const sorted = [...events].sort(
      (a, b) => Number(a.timestamp) - Number(b.timestamp),
    );

    return filterSameStateKey(sorted);
  }, [events]);

  /**Events with date dividers */
  const eventsWithDividers = useMemo(() => {
    return addDateDividers(sortedEvents);
  }, [sortedEvents]);

  const handleLoadMore = async () => {
    setShowScrollDown(false);
    await loadMoreMessages();
  };

  const handleScrollDown = () => {
    flatListRef.current?.scrollToEnd({ animated: true });
    setShowScrollDown(false);
  };

  const handleOnScroll = ({
    nativeEvent,
  }: NativeSyntheticEvent<NativeScrollEvent>) => {
    const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
    const paddingToBottom = 100;
    const atBottom =
      layoutMeasurement.height + contentOffset.y >=
      contentSize.height - paddingToBottom;
    isAtBottomRef.current = atBottom;
    if (!atBottom) return;
    setShowScrollDown(false);
    markAsRead();
  };

  // Show scroll down button if not at bottom and not own message
  useEffect(() => {
    if (isAtBottomRef.current || sortedEvents[0]?.isOwn) return;

    setShowScrollDown(true);
  }, [sortedEvents]);

  const handleStartCall = () => {
    if (!client || !room) {
      console.error("Client or room not available");
      return;
    }

    navigation.navigate("elementCall", {
      roomId,
      roomName: room.displayName(),
    });
  };

  if (!room) return null;

  return (
    <Screen hideTopSafeArea scrollable={false}>
      <RoomHeader
        room={room}
        roomMembers={roomMembers}
        hasActiveCall={hasActiveCall ?? false}
        hasNoCallOption={hasNoCallOption}
        topInset={insets.top}
        onBack={() => navigation.goBack()}
        onRoomDetails={() => navigation.navigate("roomDetails", { room })}
        onStartCall={handleStartCall}
      />

      {loadingMessage ? (
        <Loading />
      ) : (
        <KeyboardAvoidingView style={{ flex: 1 }} behavior="padding">
          {refreshing && (
            <Block align="center" justify="center" width="100%" paddings={40}>
              <ActivityIndicator size="large" color={Colors.primary} />
            </Block>
          )}
          <FlatList
            ref={flatListRef}
            data={eventsWithDividers}
            keyExtractor={(item) => {
              if (item.type === "divider") return item.id;

              return getEventId(item.data) ?? "";
            }}
            extraData={updateTrigger}
            contentContainerStyle={styles.listContent}
            onContentSizeChange={() => {
              if (!isAtBottomRef.current) return;
              // Auto-scroll only if already at the bottom
              flatListRef.current?.scrollToEnd({ animated: false });
            }}
            onRefresh={handleLoadMore}
            refreshing={refreshing}
            onScroll={handleOnScroll}
            renderItem={({ item }) => {
              if (item.type === "divider") {
                return <DateDivider date={item.date} />;
              }

              // For events, calculate the index in the original sortedEvents array
              const eventIndex = sortedEvents.findIndex(
                (e) => getEventId(e) === getEventId(item.data),
              );

              return (
                <SingleMessageType
                  event={item.data}
                  isPreviousSameSender={handleIsPreviousSameSender(
                    sortedEvents,
                    item.data,
                    eventIndex,
                  )}
                />
              );
            }}
          />
          {showScrollDown && (
            <Block
              absolute
              offsets={{ right: 0, bottom: 100 }}
              align="center"
              justify="center"
              width="100%"
            >
              <Button.Outline size="medium" onPress={handleScrollDown}>
                <Text>New messages</Text>
                <Image source={require("assets/icons/arrow-down.png")} />
              </Button.Outline>
            </Block>
          )}
          <RoomInput roomId={roomId} />
        </KeyboardAvoidingView>
      )}
    </Screen>
  );
};

const styles = StyleSheet.create({
  image: {
    width: 32,
    height: 32,
    borderRadius: 48,
  },
  listContent: {
    paddingHorizontal: 20,
    paddingTop: 12,
    paddingBottom: 20,
  },
  callButton: {
    width: 36,
    height: 36,
    borderRadius: 18,
    justifyContent: "center",
    alignItems: "center",
  },
  callIcon: {
    width: 20,
    height: 20,
    resizeMode: "contain",
  },
  callButtonCustom: {
    backgroundColor: "rgba(255, 255, 255, 0.2)",
    borderRadius: 18,
    paddingHorizontal: 12,
    paddingVertical: 8,
  },
  chatButton: {
    display: "flex",
    gap: 12,
    flex: 1,
    flexDirection: "column",
  },
  phoneIcon: {
    width: 16,
    height: 16,
  },
  blurOverlay: {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    zIndex: 1,
    opacity: 0.5,
    width: "120%",
    pointerEvents: "none",
  },
});

