     1→import type {
     2→  EventTimelineItem,
     3→  RoomInterface,
     4→  TaskHandleInterface,
     5→  TimelineInterface,
     6→} from "@unomed/react-native-matrix-sdk";
     7→import {
     8→  DateDividerMode,
     9→  ReceiptType,
    10→  TimelineDiff_Tags,
    11→  TimelineFilter,
    12→  TimelineFocus,
    13→  TimelineReadReceiptTracking,
    14→} from "@unomed/react-native-matrix-sdk";
    15→import { getEventId } from "modules/matrix-client/utils";
    16→import { useEffect, useRef, useState } from "react";
    17→
    18→interface UseRoomTimelineProps {
    19→  room: RoomInterface | undefined;
    20→  roomId: string;
    21→}
    22→
    23→export const useRoomTimeline = ({ room, roomId }: UseRoomTimelineProps) => {
    24→  const [events, setEvents] = useState<EventTimelineItem[]>([]);
    25→  const [loadingMessage, setLoadingMessage] = useState(true);
    26→  const [refreshing, setRefreshing] = useState(false);
    27→  const [updateTrigger, setUpdateTrigger] = useState(0);
    28→  const eventIdsRef = useRef<Set<string>>(new Set());
    29→  const timelineRef = useRef<TimelineInterface | null>(null);
    30→  const isPaginatingRef = useRef(false);
    31→  const timelinePaginateNumber = useRef<number>(20);
    32→
    33→  const upsertEvents = (incoming: EventTimelineItem[]) => {
    34→    setEvents((prev) => {
    35→      const next = [...prev];
    36→      for (const e of incoming) {
    37→        const id = getEventId(e);
    38→        if (!id) continue;
    39→        if (!eventIdsRef.current.has(id)) {
    40→          eventIdsRef.current.add(id);
    41→          next.push(e);
    42→        }
    43→      }
    44→      return next;
    45→    });
    46→  };
    47→
    48→  const markAsRead = async () => {
    49→    if (!room) return;
    50→
    51→    try {
    52→      await room.markAsRead(ReceiptType.Read);
    53→    } catch (error) {
    54→      console.error("Failed to mark room as read:", error);
    55→    }
    56→  };
    57→
    58→  const loadMoreMessages = async () => {
    59→    if (!room || !timelineRef.current) return;
    60→
    61→    isPaginatingRef.current = true;
    62→    setRefreshing(true);
    63→
    64→    try {
    65→      await timelineRef.current.paginateBackwards(
    66→        timelinePaginateNumber.current,
    67→      );
    68→      timelinePaginateNumber.current += 20;
    69→    } catch (error) {
    70→      console.error("Failed to load more messages:", error);
    71→    } finally {
    72→      setRefreshing(false);
    73→      isPaginatingRef.current = false;
    74→    }
    75→  };
    76→
    77→  useEffect(() => {
    78→    if (!room) return;
    79→
    80→    // Reset state when room changes
    81→    setEvents([]);
    82→    eventIdsRef.current.clear();
    83→
    84→    let timelineListenerHandle: TaskHandleInterface | null = null;
    85→
    86→    const initRoomTimeline = async () => {
    87→      try {
    88→        const timeline = await room.timelineWithConfiguration({
    89→          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
    90→          filter: new TimelineFilter.All(),
    91→          internalIdPrefix: undefined,
    92→          dateDividerMode: DateDividerMode.Daily,
    93→          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
    94→          reportUtds: false,
    95→        });
    96→
    97→        // Store timeline in ref for reuse in pagination
    98→        timelineRef.current = timeline;
    99→
   100→        await timeline.paginateBackwards(timelinePaginateNumber.current);
   101→        timelinePaginateNumber.current += 20;
   102→        setLoadingMessage(false);
   103→
   104→        // Set up timeline listener for real-time updates
   105→        timelineListenerHandle = await timeline.addListener({
   106→          onUpdate: (diffs) => {
   107→            markAsRead();
   108→            // Trigger re-render to update read receipts and other event properties
   109→            setUpdateTrigger((prev) => prev + 1);
   110→            diffs.forEach((diff) => {
   111→              const change = diff.tag;
   112→              switch (change) {
