import type {
  EventTimelineItem,
  RoomInterface,
  TaskHandleInterface,
  TimelineInterface,
} from "@unomed/react-native-matrix-sdk";
import {
  DateDividerMode,
  ReceiptType,
  TimelineDiff_Tags,
  TimelineFilter,
  TimelineFocus,
  TimelineReadReceiptTracking,
} from "@unomed/react-native-matrix-sdk";
import { getEventId } from "modules/matrix-client/utils";
import { useEffect, useRef, useState } from "react";

interface UseRoomTimelineProps {
  room: RoomInterface | undefined;
  roomId: string;
}

export const useRoomTimeline = ({ room, roomId }: UseRoomTimelineProps) => {
  const [events, setEvents] = useState<EventTimelineItem[]>([]);
  const [loadingMessage, setLoadingMessage] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [updateTrigger, setUpdateTrigger] = useState(0);
  const eventIdsRef = useRef<Set<string>>(new Set());
  const timelineRef = useRef<TimelineInterface | null>(null);
  const isPaginatingRef = useRef(false);
  const timelinePaginateNumber = useRef<number>(20);

  const upsertEvents = (incoming: EventTimelineItem[]) => {
    setEvents((prev) => {
      const next = [...prev];
      for (const e of incoming) {
        const id = getEventId(e);
        if (!id) continue;
        if (!eventIdsRef.current.has(id)) {
          eventIdsRef.current.add(id);
          next.push(e);
        }
      }
      return next;
    });
  };

  const markAsRead = async () => {
    if (!room) return;

    try {
      await room.markAsRead(ReceiptType.Read);
    } catch (error) {
      console.error("Failed to mark room as read:", error);
    }
  };

  const loadMoreMessages = async () => {
    if (!room || !timelineRef.current) return;

    isPaginatingRef.current = true;
    setRefreshing(true);

    try {
      await timelineRef.current.paginateBackwards(
        timelinePaginateNumber.current,
      );
      timelinePaginateNumber.current += 20;
    } catch (error) {
      console.error("Failed to load more messages:", error);
    } finally {
      setRefreshing(false);
      isPaginatingRef.current = false;
    }
  };

  useEffect(() => {
    if (!room) return;

    // Reset state when room changes
    setEvents([]);
    eventIdsRef.current.clear();

    let timelineListenerHandle: TaskHandleInterface | null = null;

    const initRoomTimeline = async () => {
      try {
        const timeline = await room.timelineWithConfiguration({
          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
          filter: new TimelineFilter.All(),
          internalIdPrefix: undefined,
          dateDividerMode: DateDividerMode.Daily,
          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
          reportUtds: false,
        });

        // Store timeline in ref for reuse in pagination
        timelineRef.current = timeline;

        await timeline.paginateBackwards(timelinePaginateNumber.current);
        timelinePaginateNumber.current += 20;
        setLoadingMessage(false);

        // Set up timeline listener for real-time updates
        timelineListenerHandle = await timeline.addListener({
          onUpdate: (diffs) => {
            markAsRead();
            // Trigger re-render to update read receipts and other event properties
            setUpdateTrigger((prev) => prev + 1);
            diffs.forEach((diff) => {
              const change = diff.tag;
              switch (change) {
                case TimelineDiff_Tags.Append: {
                  const newItems = diff.inner.values;
                  if (newItems.length) {
                    const eventItems = newItems
                      .map((i) => i.asEvent())
                      .filter((i): i is EventTimelineItem => !!i);

                    if (eventItems.length > 0) upsertEvents(eventItems);
                  }
                  break;
                }
                case TimelineDiff_Tags.Insert: {
                  const { value } = diff.inner;
                  const ev = value.asEvent();
                  if (ev) upsertEvents([ev]);
                  break;
                }
                case TimelineDiff_Tags.Set: {
                  const { index, value } = diff.inner;
                  const ev = value.asEvent();
                  if (ev) {
                    const id = getEventId(ev);
                    if (!id) break;

                    setEvents((prev) => {
                      const next = [...prev];
                      // Guard against out-of-range (indexes may include non-event items upstream)
                      if (index >= 0 && index < next.length) {
                        // Check if we're updating the same event or creating a duplicate
                        const existingId = getEventId(next[index]);
                        if (existingId === id || !eventIdsRef.current.has(id)) {
                          next[index] = ev;
                        }
                      } else {
                        // If index doesn't line up, check for duplicates before adding
                        if (!eventIdsRef.current.has(id)) {
                          next.push(ev);
                        }
                      }
                      // Rebuild Set from next
                      eventIdsRef.current = new Set(
                        next.map(getEventId).filter(Boolean) as string[],
                      );
                      return next;
                    });
                  }
                  break;
                }
                case TimelineDiff_Tags.Remove: {
                  const { index: removeIndex } = diff.inner;
                  setEvents((prev) => {
                    const next = prev.filter((_, idx) => idx !== removeIndex);
                    eventIdsRef.current = new Set(
                      next.map(getEventId).filter(Boolean) as string[],
                    );
                    return next;
                  });
                  break;
                }
                case TimelineDiff_Tags.PushFront: {
                  const { value } = diff.inner;
                  const ev = value.asEvent();
                  if (ev) {
                    const id = getEventId(ev);
                    if (!id) break;

                    setEvents((prev) => {
                      // Check for duplicate inside setState to prevent race conditions
                      if (eventIdsRef.current.has(id)) return prev;
                      eventIdsRef.current.add(id);
                      return [ev, ...prev];
                    });
                  }
                  break;
                }
                case TimelineDiff_Tags.PushBack: {
                  const { value } = diff.inner;
                  const ev = value.asEvent();
                  if (ev) {
                    const id = getEventId(ev);
                    if (!id) break;

                    setEvents((prev) => {
                      // Check for duplicate inside setState to prevent race conditions
                      if (eventIdsRef.current.has(id)) return prev;
                      eventIdsRef.current.add(id);
                      return [...prev, ev];
                    });
                  }
                  break;
                }
                case TimelineDiff_Tags.Reset: {
                  const resetItems = diff.inner.values;
                  if (resetItems.length) {
                    const eventItems = resetItems
                      .map((i) => i.asEvent())
                      .filter((i): i is EventTimelineItem => !!i);

                    // Deduplicate events in case Reset contains duplicates
                    const seenIds = new Set<string>();
                    const uniqueEvents: EventTimelineItem[] = [];

                    for (const event of eventItems) {
                      const id = getEventId(event);
                      if (id && !seenIds.has(id)) {
                        seenIds.add(id);
                        uniqueEvents.push(event);
                      }
                    }

                    eventIdsRef.current = seenIds;
                    setEvents(uniqueEvents);
                  }
                  break;
                }
                case TimelineDiff_Tags.Truncate: {
                  const { length: cut } = diff.inner;
                  setEvents((prev) => {
                    const next = prev.slice(0, cut);
                    eventIdsRef.current = new Set(
                      next.map(getEventId).filter(Boolean) as string[],
                    );
                    return next;
                  });
                  break;
                }
                default:
                  console.log("Unknown timeline change type:", change);
              }
            });
          },
        });
      } catch (error) {
        console.error("Failed to initialize room timeline:", error);
        return null;
      }
    };

    initRoomTimeline();

    return () => {
      timelineListenerHandle?.cancel?.();
      timelineRef.current = null;
    };
  }, [roomId]);

  useEffect(() => {
    markAsRead().catch(console.error);
  }, []);

  return {
    events,
    loadingMessage,
    refreshing,
    timelineRef,
    isPaginatingRef,
    updateTrigger,
    loadMoreMessages,
    markAsRead,
  };
};

