  event: EventTimelineItem;
  isPreviousSameSender: boolean;
}

const getEventType = (event: EventTimelineItem) => {
  if (
    event.content.tag === TimelineItemContent_Tags.RtcNotification ||
    event.content.tag === TimelineItemContent_Tags.CallInvite
  ) {
    return "call";
  }
  if (event.content.tag === TimelineItemContent_Tags.State) {
    const stateContent = event.content.inner.content;
    // if (
    //   stateContent.tag === OtherState_Tags.Custom &&
    //   stateContent.inner?.eventType === "org.matrix.msc3401.call.member"
    // ) {
    //   return "call";
    // }

    if (stateContent.tag.includes("Room")) return "room";
  }

  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;

      if (msgType?.tag === MessageType_Tags.Text) {
        return "text";
      } else if (msgType?.tag === MessageType_Tags.Image) {
        return "image";
      } else if (msgType?.tag === MessageType_Tags.File) {
        return "file";
      } else if (msgType?.tag === MessageType_Tags.Video) {
        return "video";
      } else if (msgType?.tag === MessageType_Tags.Audio) {
        return "audio";
      } else if (msgType?.tag === MessageType_Tags.Other) {
        return "other";
      } else {
        return "unkown";
      }
    }

    if (kind?.tag === MsgLikeKind_Tags.UnableToDecrypt) {
      return "unableToDecrypt";
    }
  }
  if (event.content.tag === TimelineItemContent_Tags.RoomMembership) {
    return "membership";
  }
  if (event.content.tag === TimelineItemContent_Tags.ProfileChange) {
    return "profile";
  }
  return "unkown";
};

const getTextContent = (event: EventTimelineItem): string => {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.Text) {
        return kind.inner.content.body;
      }
    }
  }
  return "";
};

const getImageContent = (
  event: EventTimelineItem,
): ImageMessageContent | null => {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.Image) {
        return msgType.inner.content;
      }
    }
  }
  return null;
};

const getAudioContent = (
  event: EventTimelineItem,
): AudioMessageContent | null => {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.Audio) {
        return msgType.inner.content;
      }
    }
  }
  return null;
};

const getVideoContent = (
  event: EventTimelineItem,
): VideoMessageContent | null => {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.Video) {
        return msgType.inner.content;
      }
    }
  }
  return null;
};

const getOtherContent = (event: EventTimelineItem) => {
  const senderName =
    event.senderProfile?.tag === "Ready"
      ? event.senderProfile?.inner?.displayName || ""
      : "";
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.Other) {
        if (msgType.inner.msgtype === "m.key.verification.request") {
          return senderName
            ? `${senderName} requested verification`
            : "Requested verification";
        }

        return kind.inner.content.body;
      }
    }
  }
  return "";
};

export const SingleMessageType: FC<Props> = ({
  event,
  isPreviousSameSender,
}) => {
  if (!event) return null;

  switch (getEventType(event)) {
    case "text": {
      const content = getTextContent(event);
      return (
        <TextMessage
          event={event}
          content={content}
          isPreviousSameSender={isPreviousSameSender}
        />
      );
    }
    case "image": {
      const content = getImageContent(event);
      if (!content) return null;
      return (
        <ImageMessage
          event={event}
          content={content}
          isPreviousSameSender={isPreviousSameSender}
        />
      );
    }
    case "audio": {
      const content = getAudioContent(event);
      if (!content) return null;
      return (
        <VoiceMessage
          event={event}
          content={content}
          isPreviousSameSender={isPreviousSameSender}
        />
      );
    }
    case "video": {
      const content = getVideoContent(event);
      if (!content) return null;
      return (
        <VideoMessage
          event={event}
          content={content}
          isPreviousSameSender={isPreviousSameSender}
        />
      );
    }
    case "other": {
      const content = getOtherContent(event);
      return <OtherMessage event={event} content={content} />;
    }
    case "call": {
      return (
        <CallMessage
          event={event}
          isPreviousSameSender={isPreviousSameSender}
        />
      );
    }
    case "membership": {
      return <MembershipInfoMessage event={event} />;
    }
    case "profile": {
      return <ProfileInfoMessage event={event} />;
    }
    case "room": {
      return <RoomInfoMessage event={event} />;
    }
    case "unableToDecrypt": {
      return <UnableToDecryptMessage event={event} />;
    }
    default:
      return null;
  }
};

