     1→import { useAtomValue, useSetAtom } from "jotai";
     2→import { MatrixService } from "modules/matrix-client/services";
     3→import { type FC, useEffect, useState } from "react";
     4→import { Alert, Button, Modal, StyleSheet, Text, View } from "react-native";
     5→import Toast from "react-native-toast-message";
     6→import { Loading } from "shared/components";
     7→import { MatrixAtoms } from "../jotai";
     8→
     9→type VerificationState = {
    10→  isVerifying: boolean;
    11→  stage: "request" | "accepted" | "emojis";
    12→  emojis: Array<{ symbol: string; description: string }> | null;
    13→  senderName: string | null;
    14→  senderId: string | null;
    15→  flowId: string | null;
    16→};
    17→
    18→export const VerificationProvider: FC = () => {
    19→  const client = useAtomValue(MatrixAtoms.matrixClient);
    20→  const syncService = useAtomValue(MatrixAtoms.syncService);
    21→  const [matchLoading, setMatchLoading] = useState(false);
    22→  const [startLoading, setStartLoading] = useState(false);
    23→  const [verificationState, setVerificationState] = useState<VerificationState>(
    24→    {
    25→      isVerifying: false,
    26→      stage: "request",
    27→      emojis: null,
    28→      senderName: null,
    29→      senderId: null,
    30→      flowId: null,
    31→    },
    32→  );
    33→  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
    34→
    35→  useEffect(() => {
    36→    if (!client || !syncService) return;
    37→    // Set up verification listeners when component mounts
    38→    const setupVerificationListeners = async () => {
    39→      try {
    40→        const unsubscribe = await MatrixService.setupVerification(
    41→          // On verification request received
    42→          (details) => {
    43→            console.log(
    44→              "Verification request from:",
    45→              details.senderProfile.displayName,
    46→            );
    47→
    48→            setVerificationState({
    49→              isVerifying: true,
    50→              stage: "request",
    51→              emojis: null,
    52→              senderName:
    53→                details.senderProfile.displayName ||
    54→                details.senderProfile.userId,
    55→              senderId: details.senderProfile.userId,
    56→              flowId: details.flowId,
    57→            });
    58→          },
    59→          // On emojis received
    60→          (emojis) => {
    61→            console.log("Emojis received:", emojis);
    62→            setMatchLoading(false);
    63→            setStartLoading(false);
    64→            setVerificationStatus("emojis");
    65→            setVerificationState((prev) => ({
    66→              ...prev,
    67→              isVerifying: true,
    68→              stage: "emojis",
    69→              emojis,
    70→              senderName: prev.senderName ?? "the other device",
    71→            }));
    72→          },
    73→          // On state change
    74→          (state) => {
    75→            console.log("Verification state changed:", state);
    76→
    77→            if (state === "success") {
    78→              setVerificationStatus("success");
    79→              setMatchLoading(false);
    80→              setStartLoading(false);
    81→              Toast.show({
    82→                type: "success",
    83→                text1: "Device verified successfully! 🎉",
    84→              });
    85→              setVerificationState({
    86→                isVerifying: false,
    87→                stage: "request",
    88→                emojis: null,
    89→                senderName: null,
    90→                senderId: null,
    91→                flowId: null,
    92→              });
    93→            } else if (state === "failed") {
    94→              setVerificationStatus("failed");
    95→              setMatchLoading(false);
    96→              setStartLoading(false);
    97→              Toast.show({
    98→                type: "error",
    99→                text1: "Verification failed",
   100→              });
   101→              setVerificationState({
   102→                isVerifying: false,
   103→                stage: "request",
   104→                emojis: null,
   105→                senderName: null,
   106→                senderId: null,
   107→                flowId: null,
   108→              });
   109→            } else if (state === "cancelled") {
   110→              setVerificationStatus("cancelled");
   111→              setMatchLoading(false);
   112→              setStartLoading(false);
   113→              Toast.show({
   114→                type: "error",
   115→                text1: "Verification cancelled",
   116→              });
   117→              setVerificationState({
   118→                isVerifying: false,
   119→                stage: "request",
   120→                emojis: null,
   121→                senderName: null,
   122→                senderId: null,
   123→                flowId: null,
   124→              });
   125→            } else if (state === "emojis") {
   126→              setVerificationStatus("emojis");
   127→            } else if (state === "accepted") {
   128→              setVerificationStatus("accepted");
   129→              setVerificationState((prev) => ({
   130→                ...prev,
   131→                stage: "accepted",
   132→              }));
   133→            }
   134→          },
   135→        );
   136→        console.log("✅ Verification listeners set up");
   137→        return unsubscribe;
   138→      } catch (error) {
   139→        console.error("Failed to set up verification:", error);
   140→      } finally {
   141→        setVerificationStatus("idle");
   142→      }
   143→    };
   144→
   145→    setupVerificationListeners();
   146→  }, [client, syncService]);
   147→
   148→  const handleEmojiMatch = async (match: boolean) => {
   149→    try {
   150→      if (match) {
   151→        await MatrixService.approveVerification();
   152→      } else {
   153→        await MatrixService.declineVerification();
   154→        Alert.alert(
   155→          "Verification Declined",
   156→          "The emojis didn't match. This could indicate a security issue.",
   157→        );
   158→      }
   159→    } catch (error) {
   160→      console.error("Failed to complete verification:", error);
   161→      Alert.alert("Error", "Failed to complete verification");
   162→    }
   163→  };
   164→
   165→  const handleAcceptVerification = async () => {
   166→    if (!verificationState.senderId || !verificationState.flowId) return;
   167→    try {
   168→      await MatrixService.acknowledgeVerification(
   169→        verificationState.senderId,
   170→        verificationState.flowId,
   171→      );
   172→      await MatrixService.acceptVerificationRequest();
   173→      setVerificationState((prev) => ({
   174→        ...prev,
   175→        stage: "accepted",
   176→      }));
   177→    } catch (error) {
   178→      console.error("Failed to accept verification:", error);
   179→      Alert.alert("Error", "Failed to accept verification");
   180→    }
   181→  };
   182→
   183→  const handleStartEmojiVerification = async () => {
   184→    try {
   185→      setStartLoading(true);
   186→      await MatrixService.startVerification();
   187→    } catch (error) {
   188→      console.error("Failed to start emoji verification:", error);
   189→      setStartLoading(false);
   190→      Alert.alert("Error", "Failed to start emoji verification");
   191→    }
   192→  };
   193→
   194→  const handleCancelVerification = async () => {
   195→    try {
   196→      await MatrixService.cancelVerification();
   197→      setVerificationStatus("cancelled");
   198→      setVerificationState({
   199→        isVerifying: false,
   200→        stage: "request",
   201→        emojis: null,
   202→        senderName: null,
   203→        senderId: null,
   204→        flowId: null,
   205→      });
   206→    } catch (error) {
   207→      console.error("Failed to cancel verification:", error);
   208→      Alert.alert("Error", "Failed to cancel verification");
   209→    }
   210→  };
   211→
   212→  return (
   213→    <>
   214→      <Modal
   215→        visible={verificationState.isVerifying}
   216→        transparent={true}
   217→        animationType="slide"
   218→      >
   219→        <View style={styles.modalOverlay}>
   220→          <View style={styles.modalContent}>
   221→            <Text style={styles.modalTitle}>Verify Device</Text>
   222→            {verificationState.stage === "request" && (
   223→              <>
   224→                <Text style={styles.modalSubtitle}>
   225→                  {verificationState.senderName} wants to verify this device.
   226→                </Text>
   227→                <Text style={styles.modalInstruction}>
   228→                  Accept the request to continue.
   229→                </Text>
   230→                <View style={styles.buttonContainer}>
   231→                  <Button
   232→                    title="Ignore"
   233→                    onPress={handleCancelVerification}
   234→                    color="#ff3b30"
   235→                  />
   236→                  <Button
   237→                    title="Accept"
   238→                    onPress={handleAcceptVerification}
   239→                    color="#34c759"
   240→                  />
   241→                </View>
   242→              </>
   243→            )}
   244→
   245→            {verificationState.stage === "accepted" && (
   246→              <>
   247→                <Text style={styles.modalSubtitle}>
   248→                  Request accepted. Start emoji verification.
   249→                </Text>
   250→                <View style={styles.buttonContainer}>
   251→                  <Button
   252→                    title="Ignore"
   253→                    onPress={handleCancelVerification}
   254→                    color="#ff3b30"
   255→                  />
   256→                  <Button
   257→                    title={
   258→                      startLoading
   259→                        ? "Starting emoji verification..."
   260→                        : "Start emoji verification"
   261→                    }
   262→                    onPress={handleStartEmojiVerification}
   263→                    color="#34c759"
   264→                  />
   265→                </View>
   266→              </>
   267→            )}
   268→
   269→            {verificationState.stage === "emojis" && (
   270→              <>
   271→                <Text style={styles.modalSubtitle}>
   272→                  Compare these emojis with {verificationState.senderName}
   273→                </Text>
   274→
   275→                <View style={styles.emojiContainer}>
   276→                  {verificationState.emojis?.map((emoji, index) => (
   277→                    <View key={index} style={styles.emojiItem}>
   278→                      <Text style={styles.emojiSymbol}>{emoji.symbol}</Text>
   279→                      <Text style={styles.emojiDescription}>
   280→                        {emoji.description}
   281→                      </Text>
   282→                    </View>
   283→                  ))}
   284→                </View>
   285→
   286→                <Text style={styles.modalInstruction}>
   287→                  Do these emojis match on both devices?
   288→                </Text>
   289→
   290→                <View style={styles.buttonContainer}>
   291→                  {matchLoading ? (
   292→                    <Loading
   293→                      text="Waiting verification from other device..."
   294→                      isFullScreen={false}
   295→                    />
   296→                  ) : (
   297→                    <>
   298→                      <Button
   299→                        title="They Don't Match"
